        /// ```
        pub fn order_item_count(locale: Locale, count: i64) -> String {
            match locale {
                Locale::Cs => {
                    match ::codon::plural::PluralRule::Czech.category(count) {
                        ::codon::plural::Category::One => String::from("1 položka"),
                        _ => format!("{count} položek"),
                    }
                }
                Locale::De => {
                    match ::codon::plural::PluralRule::OneOther.category(count) {
                        ::codon::plural::Category::One => String::from("1 Artikel"),
                        _ => format!("{count} Artikel"),
                    }
                }
            }
        }

