        /// `delivery_estimate.result_html`
        ///
        /// ```text
        /// cs: Doprava – <strong>%{place}</strong>: cca %{km} km, tam i zpět %{round_trip_km} km × %{rate} = <stron…
        /// de: Lieferung nach <strong>%{place}</strong>: ca. %{km} km, hin und zurück %{round_trip_km} km × %{rate}…
        /// ```
        pub fn result(
            locale: Locale,
            km: impl ::codon::HtmlArg,
            place: impl ::codon::HtmlArg,
            price: impl ::codon::HtmlArg,
            rate: impl ::codon::HtmlArg,
            round_trip_km: impl ::codon::HtmlArg,
        ) -> ::codon::Html {
            match locale {
                Locale::Cs => {
                    let mut html = String::with_capacity(159);
                    html.push_str("Doprava – <strong>");
                    ::codon::HtmlArg::push_html(&place, &mut html);
                    html.push_str("</strong>: cca ");
                    ::codon::HtmlArg::push_html(&km, &mut html);
                    html.push_str(" km, tam i zpět ");
                    ::codon::HtmlArg::push_html(&round_trip_km, &mut html);
                    html.push_str(" km × ");
                    ::codon::HtmlArg::push_html(&rate, &mut html);
                    html.push_str(" = <strong>≈ ");
                    ::codon::HtmlArg::push_html(&price, &mut html);
                    html.push_str("</strong>");
                    ::codon::Html::from_trusted(html)
                }
                Locale::De => {
                    let mut html = String::with_capacity(166);
                    html.push_str("Lieferung nach <strong>");
                    ::codon::HtmlArg::push_html(&place, &mut html);
                    html.push_str("</strong>: ca. ");
                    ::codon::HtmlArg::push_html(&km, &mut html);
                    html.push_str(" km, hin und zurück ");
                    ::codon::HtmlArg::push_html(&round_trip_km, &mut html);
                    html.push_str(" km × ");
                    ::codon::HtmlArg::push_html(&rate, &mut html);
                    html.push_str(" = <strong>≈ ");
                    ::codon::HtmlArg::push_html(&price, &mut html);
                    html.push_str("</strong>");
                    ::codon::Html::from_trusted(html)
                }
            }
        }

