        /// `legal.terms_content_html`
        ///
        /// ```text
        /// cs: <h2>1. Úvodní ustanovení</h2> <p>Tyto obchodní podmínky (dále jen „obchodní podmínky") upravují vzáj…
        /// de: <h2>1. Einleitende Bestimmungen</h2> <p>Diese Allgemeinen Geschäftsbedingungen (im Folgenden „AGB") …
        /// ```
        pub fn terms_content(
            locale: Locale,
            delivery_rate: impl ::codon::HtmlArg,
        ) -> ::codon::Html {
            match locale {
                Locale::Cs => {
                    let mut html = String::with_capacity(7387);
                    html.push_str(
                        "<h2>1. Úvodní ustanovení</h2>\n<p>Tyto obchodní podmínky (dále jen „obchodní podmínky\") upravují vzájemná práva a povinnosti smluvních stran vzniklé v souvislosti nebo na základě kupní smlouvy uzavírané mezi:</p>\n<p><strong>Štěpán Merta</strong><br>\nPila Derflice<br>\nMísto podnikání: Derflice 66, 671 28 Znojmo<br>\nKorespondenční a fakturační adresa: Meruňková 206, 671 81 Nový Šaldorf – Sedlešovice<br>\nIČ: 45665451<br>\nDIČ: CZ6909094742<br>\nFyzická osoba podnikající dle živnostenského zákona, nezapsaná v obchodním rejstříku.<br>\nE-mail: stepan.merta@seznam.cz<br>\nTelefon: +420 602 446 339, +420 515 235 527<br>\nProvozní doba: pondělí – pátek, 7:00 – 15:30</p>\n<p>(dále jen „prodávající\") a kupujícím, který prostřednictvím e-shopu na adrese piladerflice.cz učiní objednávku zboží (dále jen „kupující\").</p>\n<p>Znění obchodních podmínek může prodávající měnit či doplňovat. Tímto ustanovením nejsou dotčena práva a povinnosti vzniklá po dobu účinnosti předchozího znění obchodních podmínek.</p>\n\n<h2>2. Uzavření kupní smlouvy</h2>\n<p>Objednávku zboží kupující odešle prostřednictvím objednávkového formuláře na e-shopu. Odesláním objednávky kupující stvrzuje, že se seznámil s těmito obchodními podmínkami a že s nimi souhlasí.</p>\n<p>Kupní smlouva mezi prodávajícím a kupujícím vzniká okamžikem doručení potvrzení objednávky ze strany prodávajícího na e-mailovou adresu kupujícího.</p>\n\n<h2>3. Cena zboží a platební podmínky</h2>\n<p>Ceny zboží uvedené na e-shopu jsou platné v okamžiku odeslání objednávky a jsou uváděny včetně DPH.</p>\n<p>Platbu za zboží lze provést jedním z následujících způsobů:</p>\n<ul>\n  <li><strong>Hotově při osobním odběru</strong> – na adrese provozovny Derflice 66, 671 28 Znojmo.</li>\n  <li><strong>Bankovním převodem</strong> – na základě zálohové (proforma) faktury zaslané kupujícímu po přijetí objednávky; zboží je expedováno po připsání platby na účet prodávajícího.</li>\n</ul>\n<p>Prodávající v současné době nenabízí platbu prostřednictvím platební karty online.</p>\n\n<h2>4. Dodací podmínky</h2>\n<p>Kupující si může zvolit jeden z následujících způsobů dodání:</p>\n<ul>\n  <li><strong>Osobní odběr</strong> – zdarma, na adrese provozovny Derflice 66, 671 28 Znojmo, po předchozí domluvě.</li>\n  <li><strong>Doprava na adresu</strong> – cena dopravy činí ",
                    );
                    ::codon::HtmlArg::push_html(&delivery_rate, &mut html);
                    html.push_str(
                        " Kč (včetně DPH) za každý ujetý kilometr, počítáno tam i zpět mezi provozovnou v Derflicích a doručovací adresou. Vzdálenost se počítá automaticky podle doručovací adresy a orientační cena dopravy je zobrazena v souhrnu objednávky a zahrnuta v celkové ceně; konečnou cenu dopravy prodávající potvrdí po přijetí objednávky. Celé objednané množství se doveze jednou jízdou. Nepodaří-li se vzdálenost spočítat, je cena dopravy kupujícímu sdělena individuálně po přijetí objednávky. Prodávající zajišťuje rozvoz zejména v oblasti jižní Moravy a přilehlého severního Rakouska.</li>\n</ul>\n<p>Termín dodání či předání zboží k osobnímu odběru je dohodnut individuálně s ohledem na dostupnost zboží a kapacitu prodávajícího; není-li dohodnuto jinak, dodá prodávající zboží v přiměřené lhůtě.</p>\n\n<h2>5. Odstoupení od smlouvy</h2>\n<p>V souladu s § 1829 občanského zákoníku má kupující, je-li spotřebitelem, právo odstoupit od kupní smlouvy uzavřené distančním způsobem bez udání důvodu ve lhůtě 14 dnů ode dne převzetí zboží, a to zasláním písemného odstoupení na e-mail nebo poštovní adresu prodávajícího.</p>\n<p>V souladu s § 1837 písm. d) občanského zákoníku nelze odstoupit od smlouvy v případě zboží, které bylo upraveno podle přání kupujícího nebo pro jeho osobu (např. řezivo, trámy či fošny vyrobené na míru dle individuálně zadaných rozměrů).</p>\n<p>Zboží je kupující povinen vrátit prodávajícímu nepoškozené a bez známek užívání, je-li to s ohledem na jeho povahu možné, a to do 14 dnů od odstoupení od smlouvy. Náklady spojené s vrácením zboží nese kupující.</p>\n\n<h2>6. Práva z vadného plnění a reklamace</h2>\n<p>Práva a povinnosti smluvních stran ohledně práv z vadného plnění se řídí příslušnými obecně závaznými právními předpisy, zejména § 2099 a násl. a § 2158 a násl. občanského zákoníku.</p>\n<p>Je-li kupující spotřebitelem, odpovídá prodávající za to, že zboží při převzetí nemá vady, a to po dobu 24 měsíců od převzetí zboží.</p>\n<p>Reklamaci lze uplatnit e-mailem na adrese stepan.merta@seznam.cz nebo osobně na adrese provozovny. Prodávající rozhodne o reklamaci a vyřídí ji nejpozději do 30 dnů ode dne jejího uplatnění, nedohodne-li se s kupujícím na delší lhůtě.</p>\n<p>Vzhledem k povaze zboží (přírodní materiál – dřevo) se za vadu nepovažují drobné rozdíly v kresbě, barvě nebo mírné rozdíly v rozměrech způsobené přirozenými vlastnostmi dřeva, pokud nebrání obvyklému užití zboží.</p>\n\n<h2>7. Ochrana osobních údajů</h2>\n<p>Prodávající zpracovává osobní údaje kupujícího (jméno, příjmení, adresa, telefon, e-mail, popř. IČ/DIČ při nákupu na firmu) výhradně za účelem vyřízení objednávky, plnění kupní smlouvy a plnění zákonných povinností (např. účetních). Správcem osobních údajů je Štěpán Merta, IČ: 45665451.</p>\n<p>Osobní údaje nejsou předávány třetím osobám s výjimkou subjektů nezbytných pro doručení zboží (dopravce), poskytovatele služby pro výpočet vzdálenosti doručovací adresy (openrouteservice, HeiGIT gGmbH, Německo) a subjektů vyžadovaných zákonem (např. finanční správa).</p>\n<p>Kupující má právo na přístup ke svým osobním údajům, jejich opravu či výmaz, popřípadě omezení zpracování, a právo vznést námitku proti zpracování, jakož i právo podat stížnost u Úřadu pro ochranu osobních údajů.</p>\n\n<h2>8. Mimosoudní řešení sporů</h2>\n<p>V případě, že mezi prodávajícím a kupujícím spotřebitelem dojde ke vzniku spotřebitelského sporu, má kupující právo na jeho mimosoudní řešení. Subjektem mimosoudního řešení spotřebitelských sporů je Česká obchodní inspekce, Ústřední inspektorát – oddělení ADR, se sídlem Štěpánská 567/15, 120 00 Praha 2, internetová adresa: <a href=\"https://adr.coi.cz\" target=\"_blank\" rel=\"noopener\">adr.coi.cz</a>.</p>\n\n<h2>9. Závěrečná ustanovení</h2>\n<p>Tyto obchodní podmínky se řídí právním řádem České republiky, zejména zákonem č. 89/2012 Sb., občanský zákoník, a zákonem č. 634/1992 Sb., o ochraně spotřebitele, ve znění pozdějších předpisů.</p>\n<p>Je-li některé ustanovení obchodních podmínek neplatné nebo neúčinné, nebo se takovým stane, namísto neplatných ustanovení nastoupí ustanovení, jehož smysl se neplatnému ustanovení co nejvíce přibližuje. Neplatností nebo neúčinností jednoho ustanovení není dotčena platnost ostatních ustanovení.</p>\n<p>Tyto obchodní podmínky nabývají účinnosti dnem jejich zveřejnění.</p>\n",
                    );
                    ::codon::Html::from_trusted(html)
                }
                Locale::De => {
                    let mut html = String::with_capacity(7510);
                    html.push_str(
                        "<h2>1. Einleitende Bestimmungen</h2>\n<p>Diese Allgemeinen Geschäftsbedingungen (im Folgenden „AGB\") regeln die gegenseitigen Rechte und Pflichten der Vertragsparteien im Zusammenhang mit einem Kaufvertrag, der abgeschlossen wird zwischen:</p>\n<p><strong>Štěpán Merta</strong><br>\nPila Derflice<br>\nGeschäftssitz: Derflice 66, 671 28 Znojmo, Tschechische Republik<br>\nKorrespondenz- und Rechnungsadresse: Meruňková 206, 671 81 Nový Šaldorf – Sedlešovice<br>\nSteuernummer (IČ): 45665451<br>\nUSt-IdNr. (DIČ): CZ6909094742<br>\nNatürliche Person, die gemäß dem tschechischen Gewerbegesetz unternehmerisch tätig ist und nicht im Handelsregister eingetragen ist.<br>\nE-Mail: stepan.merta@seznam.cz<br>\nTelefon: +420 602 446 339, +420 515 235 527<br>\nGeschäftszeiten: Montag – Freitag, 7:00 – 15:30 Uhr</p>\n<p>(im Folgenden „Verkäufer\") und dem Käufer, der über den Onlineshop unter piladerflice.cz eine Warenbestellung tätigt (im Folgenden „Käufer\").</p>\n<p>Der Verkäufer kann den Wortlaut der AGB ändern oder ergänzen. Rechte und Pflichten, die während der Gültigkeit der vorherigen Fassung der AGB entstanden sind, bleiben davon unberührt.</p>\n\n<h2>2. Zustandekommen des Kaufvertrags</h2>\n<p>Der Käufer sendet die Bestellung über das Bestellformular im Onlineshop ab. Mit dem Absenden der Bestellung bestätigt der Käufer, dass er diese AGB zur Kenntnis genommen hat und ihnen zustimmt.</p>\n<p>Der Kaufvertrag zwischen dem Verkäufer und dem Käufer kommt in dem Moment zustande, in dem die Bestellbestätigung des Verkäufers an die E-Mail-Adresse des Käufers zugestellt wird.</p>\n\n<h2>3. Preise und Zahlungsbedingungen</h2>\n<p>Die im Onlineshop angegebenen Warenpreise gelten zum Zeitpunkt der Bestellabsendung und verstehen sich inklusive Mehrwertsteuer.</p>\n<p>Die Zahlung kann auf eine der folgenden Arten erfolgen:</p>\n<ul>\n  <li><strong>Bar bei persönlicher Abholung</strong> – am Betriebssitz Derflice 66, 671 28 Znojmo.</li>\n  <li><strong>Per Banküberweisung</strong> – auf Grundlage einer Proforma-Rechnung, die dem Käufer nach Eingang der Bestellung zugesandt wird; der Versand erfolgt nach Zahlungseingang auf dem Konto des Verkäufers.</li>\n</ul>\n<p>Der Verkäufer bietet derzeit keine Online-Kartenzahlung an.</p>\n\n<h2>4. Lieferbedingungen</h2>\n<p>Der Käufer kann zwischen folgenden Versandarten wählen:</p>\n<ul>\n  <li><strong>Persönliche Abholung</strong> – kostenlos, am Betriebssitz Derflice 66, 671 28 Znojmo, nach vorheriger Vereinbarung.</li>\n  <li><strong>Lieferung an die Adresse</strong> – der Lieferpreis beträgt ",
                    );
                    ::codon::HtmlArg::push_html(&delivery_rate, &mut html);
                    html.push_str(
                        " CZK (inkl. MwSt.) pro gefahrenem Kilometer, berechnet hin und zurück zwischen dem Betrieb in Derflice und der Lieferadresse. Die Entfernung wird anhand der Lieferadresse automatisch berechnet; der ungefähre Lieferpreis wird in der Bestellübersicht angezeigt und ist im Gesamtpreis enthalten, den endgültigen Lieferpreis bestätigt der Verkäufer nach Eingang der Bestellung. Die gesamte bestellte Menge wird in einer Fahrt geliefert. Kann die Entfernung nicht berechnet werden, wird der Lieferpreis dem Käufer nach Eingang der Bestellung individuell mitgeteilt. Der Verkäufer liefert insbesondere in Südmähren und im angrenzenden Österreich.</li>\n</ul>\n<p>Der Liefer- bzw. Abholtermin wird individuell je nach Warenverfügbarkeit und Kapazität des Verkäufers vereinbart; sofern nichts anderes vereinbart wurde, liefert der Verkäufer die Ware innerhalb einer angemessenen Frist.</p>\n\n<h2>5. Widerrufsrecht</h2>\n<p>Gemäß § 1829 des tschechischen Bürgerlichen Gesetzbuchs hat der Käufer, sofern er Verbraucher ist, das Recht, innerhalb von 14 Tagen ab Erhalt der Ware ohne Angabe von Gründen vom im Fernabsatz geschlossenen Kaufvertrag zurückzutreten, indem er dem Verkäufer eine schriftliche Widerrufserklärung per E-Mail oder Post zusendet.</p>\n<p>Gemäß § 1837 lit. d) des Bürgerlichen Gesetzbuchs besteht kein Widerrufsrecht bei Waren, die nach den Wünschen des Käufers angefertigt wurden (z. B. nach individuellen Maßen zugeschnittenes Bau- oder Schnittholz).</p>\n<p>Der Käufer hat die Ware unbeschädigt und, soweit es die Art der Ware zulässt, ohne Gebrauchsspuren innerhalb von 14 Tagen ab Widerruf zurückzusenden. Die Kosten der Rücksendung trägt der Käufer.</p>\n\n<h2>6. Gewährleistung und Reklamation</h2>\n<p>Die Rechte und Pflichten der Vertragsparteien hinsichtlich der Mängelhaftung richten sich nach den einschlägigen Bestimmungen des tschechischen Bürgerlichen Gesetzbuchs, insbesondere §§ 2099 ff. und §§ 2158 ff.</p>\n<p>Ist der Käufer Verbraucher, haftet der Verkäufer dafür, dass die Ware bei Übergabe keine Mängel aufweist, und zwar für einen Zeitraum von 24 Monaten ab Übergabe.</p>\n<p>Reklamationen können per E-Mail an stepan.merta@seznam.cz oder persönlich am Betriebssitz geltend gemacht werden. Der Verkäufer entscheidet über die Reklamation und erledigt sie spätestens innerhalb von 30 Tagen ab Geltendmachung, sofern mit dem Käufer keine längere Frist vereinbart wurde.</p>\n<p>Aufgrund der Beschaffenheit der Ware (Naturmaterial Holz) gelten geringfügige Unterschiede in Maserung, Farbe oder leichte Maßabweichungen, die auf die natürlichen Eigenschaften des Holzes zurückzuführen sind, nicht als Mangel, sofern sie die übliche Verwendung der Ware nicht beeinträchtigen.</p>\n\n<h2>7. Datenschutz</h2>\n<p>Der Verkäufer verarbeitet personenbezogene Daten des Käufers (Name, Adresse, Telefonnummer, E-Mail, ggf. Steuernummer/USt-IdNr. bei Firmenkäufen) ausschließlich zum Zweck der Bestellabwicklung, der Erfüllung des Kaufvertrags sowie der Erfüllung gesetzlicher Pflichten (z. B. Buchhaltung). Verantwortlicher für die Datenverarbeitung ist Štěpán Merta, IČ: 45665451.</p>\n<p>Die Daten werden nicht an Dritte weitergegeben, mit Ausnahme der für die Zustellung notwendigen Personen (Transportunternehmen), des Dienstes zur Entfernungsberechnung der Lieferadresse (openrouteservice, HeiGIT gGmbH, Deutschland) sowie gesetzlich vorgeschriebener Stellen (z. B. Finanzbehörden).</p>\n<p>Der Käufer hat das Recht auf Auskunft über seine personenbezogenen Daten, deren Berichtigung oder Löschung sowie auf Einschränkung der Verarbeitung, das Recht, der Verarbeitung zu widersprechen, sowie das Recht, Beschwerde bei der zuständigen Datenschutzbehörde einzureichen.</p>\n\n<h2>8. Außergerichtliche Streitbeilegung</h2>\n<p>Kommt es zwischen dem Verkäufer und einem Käufer, der Verbraucher ist, zu einem Verbraucherstreit, hat der Käufer das Recht auf dessen außergerichtliche Beilegung. Zuständige Stelle ist die tschechische Handelsinspektion (Česká obchodní inspekce), Zentralinspektorat – Abteilung ADR, mit Sitz in Štěpánská 567/15, 120 00 Prag 2, Internetadresse: <a href=\"https://adr.coi.cz\" target=\"_blank\" rel=\"noopener\">adr.coi.cz</a>.</p>\n\n<h2>9. Schlussbestimmungen</h2>\n<p>Diese AGB unterliegen dem Recht der Tschechischen Republik, insbesondere dem Gesetz Nr. 89/2012 Slg., Bürgerliches Gesetzbuch, sowie dem Gesetz Nr. 634/1992 Slg., über den Verbraucherschutz, in der jeweils geltenden Fassung.</p>\n<p>Sollte eine Bestimmung dieser AGB unwirksam sein oder werden, tritt an ihre Stelle eine Regelung, die dem wirtschaftlichen Zweck der unwirksamen Bestimmung am nächsten kommt. Die Unwirksamkeit einer Bestimmung berührt nicht die Gültigkeit der übrigen Bestimmungen.</p>\n<p>Diese AGB treten mit dem Datum ihrer Veröffentlichung in Kraft.</p>\n",
                    );
                    ::codon::Html::from_trusted(html)
                }
            }
        }

